import sys

def main():
    data = sys.stdin.read().split()
    n, S, D = int(data[0]), int(data[1]), int(data[2])
    col = data[3]
    adj = [[] for _ in range(n)]
    for i in range(n - 1):
        u = int(data[4 + 2 * i])
        v = int(data[5 + 2 * i])
        adj[u].append(v)
        adj[v].append(u)
    bit = {'R': 1, 'G': 2, 'B': 4}
    par = [-1] * n
    depth = [0] * n
    order = [S]
    seen = [False] * n
    seen[S] = True
    for x in order:
        for y in adj[x]:
            if not seen[y]:
                seen[y] = True
                par[y] = x
                depth[y] = depth[x] + 1
                order.append(y)
    forced = [False] * n
    x = D
    while x != -1:
        forced[x] = True
        x = par[x]
    INF = 10**9
    f = []
    for v in range(n):
        b = bit[col[v]]
        f.append([0 if (m & ~b) == 0 else INF for m in range(8)])
    pairs = []
    for m in range(8):
        s = m
        while True:
            pairs.append((m, s, m ^ s))
            if s == 0:
                break
            s = (s - 1) & m
    for v in reversed(order):
        p = par[v]
        if p == -1:
            continue
        fv = f[v]
        g = [x + 1 for x in fv]
        if not forced[v]:
            g[0] = 0
        cur = f[p]
        new = [INF] * 8
        for m, s, r in pairs:
            c = cur[s] + g[r]
            if c < new[m]:
                new[m] = c
        for m in range(7, -1, -1):
            for b in (1, 2, 4):
                if not m & b and new[m | b] < new[m]:
                    new[m] = new[m | b]
        f[p] = new
    best = f[S][7]
    if best >= INF:
        print(-1)
    else:
        print(2 * best - depth[D] + 3)

